import java.sql.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; public class ResetPassword { public static void main(String[] args) { try { Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/ncp_com_db?serverTimezone=UTC", "root", ""); Statement stmt = conn.createStatement(); String hash = new BCryptPasswordEncoder().encode("password"); stmt.executeUpdate("UPDATE users SET password='" + hash + "'"); System.out.println("Passwords reset to 'password' for all users!"); } catch(Exception e) { e.printStackTrace(); } } }
